function jpHall(B, P, gy, eave, rh, wall, roof, holes){
  const lo = gMin(gy, P), y0 = lo - 1, ye = lo + eave;
  prismP(B.p(wall), P, y0, ye, true, true); for (const h of holes || []) prismP(B.p(wall), h, y0, ye, true, true);
  const ov = offP(P, -1.1), D = Math.max(2.5, Math.min(14, minHalfW(P) + 1.1));
  skelRoof(B.p(roof), ov, (holes || []).map(h => offP(h, 1.1)), ye - 0.4, rh, D, t => Math.pow(t, 1.35), 1.8);
  return lo;
}
const minHalfW = P => { const a = axesP(P); return Math.min(a.a, a.b); };
// scatter trees on a jittered grid inside polygon S, avoiding the given test
function scatter(ctx, S, step, ok, kindF, sizeF){ const bb = bbP(S); let n = 0;
  for (let x = bb[0]; x < bb[2]; x += step) for (let z = bb[1]; z < bb[3]; z += step){ const px = x + (ctx.rng() - 0.5)*step*0.8, pz = z + (ctx.rng() - 0.5)*step*0.8;
    if (!inPoly(S, px, pz) || !ok(px, pz)) continue; ctx.tree(px, pz, sizeF ? sizeF(px, pz) : 3 + ctx.rng()*1.4, kindF ? kindF(px, pz) : 'd'); n++; } return n; }


// ===================================================================================================================================
// Shinjuku — Tokyo Metropolitan Government Buildings No. 1 and No. 2, Mode Gakuen Cocoon Tower, Shinjuku Park Tower, Shinjuku
// Sumitomo Building (+ Triangle Square), and the Shinjuku Gyoen site. All on their OSM footprints (FD, local metres, +x east, +z south,
// rot 0), heights from the sources in the report. Front: no special front; the models are not rotated.
// ===================================================================================================================================
// a tower shaft with a stone / metal grid over lit glass: walls of P from y0 to y1, spandrel bands every fh, mullions every sp
function gridShaft(B, P, y0, y1, o){
  const GL = B.p(o.glass), ST = B.p(o.stone);
  prismP(GL, P, y0, y1, true, true);
  bandsP(ST, P, y0, y1, o.fh, o.bh, 0.15);
  mullP(ST, P, y0, y1, o.sp, o.mw, 0.16, o.md || 0);
  if (o.acc) mullP(B.p(o.acc), P, y0, y1, o.asp, o.aw, 0.32, 0.25);
}
// a flat roof with a parapet
function roofP(B, P, y, col, ph){ flatP(B.p(col), P, y); edgeP(B.p(col), P, y, 0.5, ph || 1.4, 0); }

// ---------------------------------------------------------------- Tokyo Metropolitan Government Building No. 1 (243 m, 48 F, 1991)
// The body (to the 33rd floor, where it splits: roof ≈ 147 m, from the 45th floor at 202 m) carries two towers; each tower steps from
// the notched square (to 176 m) to the square-and-diamond section (to 207 m: the 45th-floor observatories at 202 m) and the diamond
// (to 243 m) of the OSM building parts. Light granite grid over glass with dark granite accents.
LANDMARKS.tytmg1 = {zh:'东京都厅第一本厅舍', en:'Tokyo Metropolitan Government Building No. 1', cat:'new', r:62, h:243,
  lt:{m:1, c:'#e9eef7', k:0.62},
  build(){
    const g = new THREE.Group(), B = mkB(), F = FD.tytmg1, gf = gL('tytmg1');
    const GLS = {c:'#6f7882', m:1, fh:4.1, cw:3.2}, STN = '#d2cfc6', DRK = '#62666c';
    const o = {glass:GLS, stone:STN, fh:4.15, bh:2.1, sp:3.2, mw:1.0, acc:DRK, asp:12.8, aw:0.7};
    const SLAB = 147;
    plinthP(B.p(STN), F.ring, gf, 0.2);
    gridShaft(B, F.ring, 0, SLAB, o);
    roofP(B, F.ring, SLAB, '#b9b6ae');
    // the entrance lobby: a darker recessed band at the foot
    bandsP(B.p('#3f444a'), F.ring, 0.3, 6.5, 7, 6.2, 0.4);
    const P176 = F.parts.filter(p => p.t === 176), P207 = F.parts.filter(p => p.t === 207), P243 = F.parts.filter(p => p.t === 243);
    for (const p of P176){ gridShaft(B, p.r, SLAB, 176, o); roofP(B, p.r, 176, '#b9b6ae', 1.2); }
    for (const p of P207){ gridShaft(B, p.r, 176, 207, o); roofP(B, p.r, 207, '#b9b6ae', 1.2);
      // the observatory floor (45 F, 202 m): a glazed band lit at night
      prismP(B.p({c:'#8fa3b5', glow:'#ffe9c8', gk:0.55}), offP(p.r, -0.3), 201.5, 205.5, true, true); }
    for (const p of P243){ gridShaft(B, p.r, 207, 240, o);
      // crown: two darker storeys and the roof with a parapet, a rooftop plant box and a pair of thin masts
      prismP(B.p('#9a9b9c'), offP(p.r, -0.05), 236, 240.6, true, true); roofP(B, p.r, 240.6, '#a8a6a0', 2.0);
      const c = cenP(p.r); boxP(B.p('#9a9b9c'), 9, 2.2, 9, c[0], 240.6, c[1], Math.PI/4);
      for (const s of [-1, 1]){ segP(B.p('#d9d9d9'), [c[0] + s*2.5, 242.8, c[1] + s*2.5], [c[0] + s*2.5, 243, c[1] + s*2.5], 0.12, 4); }
      avLight(B, c[0], 242.8, c[1], 0.9);
      const k = p.r.length; for (const i of [0, Math.floor(k/3), Math.floor(2*k/3)]) avLight(B, p.r[i][0], 242.6, p.r[i][1], 0.6); }
    B.flush(g); return g; }};

