// ---------------------------------------------------------------- Mode Gakuen Cocoon Tower (203.65 m, 50 F, 2008)
// An elliptical shaft (fitted to the OSM footprint) that swells a little and tapers to a rounded top, dark glass wrapped in the white
// lattice of curved diagonal bands (two opposite families that close into long ovals).
LANDMARKS.tycocoon = {zh:'东京MODE学园蚕茧大厦', en:'Mode Gakuen Cocoon Tower', cat:'new', r:32, h:204,
  lt:{m:1, c:'#e3ecff', k:0.6},
  build(){
    const g = new THREE.Group(), B = mkB(), F = FD.tycocoon, gf = gL('tycocoon'), H = 203.65;
    const ax = axesP(F.ring), A0 = ax.sa*0.985, B0 = ax.sb*0.985, cx = ax.c[0], cz = ax.c[1], ux = ax.ux, uz = ax.uz;
    // plan scale along the height: full at the foot, swelling to 1.04 at 35 %, tapering to the rounded top
    const sc = t => t < 0.35 ? 1 + 0.04*Math.sin(t/0.35*HP) : t < 0.93 ? 1.04 - 0.36*Math.pow((t - 0.35)/0.58, 1.6) : 0.68*Math.sqrt(Math.max(0, 1 - Math.pow((t - 0.93)/0.07, 2)))*0.98 + 0.02;
    const NS = 56, pt = (th, t, off) => { const s = sc(t), a = A0*s + (off || 0), b = B0*s + (off || 0), lx = Math.cos(th)*a, lz = Math.sin(th)*b; return [cx + lx*ux - lz*uz, t*H, cz + lx*uz + lz*ux]; };
    const secs = []; for (let k = 0; k <= 48; k++){ const t = k/48, R = []; for (let i = 0; i < NS; i++) R.push(pt(i/NS*TAU, t, 0)); secs.push(R); }
    loftP(B.p({c:'#56697e', m:1, fh:4.0, cw:2.6}), secs, true);
    // plinth / ground-floor ring
    { const R = []; for (let i = 0; i < NS; i++){ const p = pt(i/NS*TAU, 0, 0.3); R.push([p[0], p[2]]); } plinthP(B.p('#cfd2d4'), R, gf, 0.3); }
    // lattice: two families of curved bands, 9 each, half a turn over the height, wavy so they close into ovals
    const LAT = B.p({c:'#f2f3f1', m:0, lc:'#f4f8ff', lk:0.9}), NB = 9, NSTEP = 90;
    for (const dir of [1, -1]) for (let k = 0; k < NB; k++){
      const th0 = k/NB*TAU; let prev = null;
      for (let s = 0; s <= NSTEP; s++){
        const t = s/NSTEP; if (t > 0.985) break;
        const th = th0 + dir*(t*PI*1.0 + 0.22*Math.sin(t*TAU*1.5)), p = pt(th, t, 0.55), q = pt(th + 0.035*dir, t + 0.004, 0.55);
        const w = 0.75 + 0.5*Math.sin(t*PI);  // band half-width (m), widest at mid-height
        const nx = p[0] - cx, nz = p[2] - cz, nl = Math.hypot(nx, nz) || 1, tx = -nz/nl, tz = nx/nl;
        const L = [p[0] - tx*w, p[1], p[2] - tz*w], R = [p[0] + tx*w, p[1], p[2] + tz*w];
        if (prev) quadP(LAT, prev[0], prev[1], R, L);
        prev = [L, R];
      }
    }
    // horizontal white rings at the foot and near the top
    for (const t of [0.012, 0.93]){ for (let i = 0; i < NS; i++){ const a = pt(i/NS*TAU, t, 0.6), b = pt((i+1)/NS*TAU, t, 0.6); quadP(LAT, a, b, [b[0], b[1] + 1.2, b[2]], [a[0], a[1] + 1.2, a[2]]); } }
    avLight(B, cx, H - 0.2, cz, 0.9);
    B.flush(g); return g; }};

// ---------------------------------------------------------------- Shinjuku Park Tower (235 m, 52 F, 1994)
// Three connected square towers of 174 / 201 / 227 m (OSM) stepping down to the north-west, each crowned by a steel-and-glass pyramid
// (to 182 / 209 / 235 m); grey granite piers with vertical glass strips and notched corners.
LANDMARKS.typarktower = {zh:'新宿柏悦大厦', en:'Shinjuku Park Tower', cat:'new', r:112, h:235,
  lt:{m:1, c:'#ffe8c8', k:0.55},
  build(){
    const g = new THREE.Group(), B = mkB(), F = FD.typarktower, gf = gL('typarktower');
    const GLS = {c:'#6b7a87', m:1, fh:4.3, cw:3.0}, STN = '#b9b5ad', DRK = '#56606a';
    for (const T of F.towers){
      const P = T.r, h = T.h;
      plinthP(B.p(STN), P, gf, 0.2);
      prismP(B.p(GLS), P, 0, h, true, true);
      mullP(B.p(STN), P, 0, h - 3, 3.0, 1.5, 0.2, 0.35);           // granite piers: strong vertical lines
      bandsP(B.p(STN), P, 6, h - 3, 4.3, 0.9, 0.18);                // thin spandrels
      bandsP(B.p(DRK), P, 0.3, 7, 8, 6.4, 0.45);                    // dark glazed base
      prismP(B.p('#8d8a84'), offP(P, -0.25), h - 3, h, true, true);  // cornice band
      roofP(B, P, h, '#8f8d88', 1.0);
      // the pyramid on a low glazed drum
      const Q = T.p, c = cenP(Q);
      prismP(B.p({c:'#7d8f9e', glow:'#ffdcae', gk:0.5}), Q, h, h + 1.6, true, true);
      pyrP(B.p({c:'#9fb0bd', glow:'#ffd9a6', gk:0.32}), Q, h + 1.6, T.t - h - 1.6, c);
      // pyramid ribs (steel frame)
      const RIB = B.p('#d6d8d8');
      for (let i = 0; i < Q.length; i++){ const a = Q[i], b = Q[(i+1) % Q.length]; segP(RIB, [a[0], h + 1.6, a[1]], [c[0], T.t, c[1]], 0.18, 4);
        for (let f = 0.2; f < 0.95; f += 0.2){ const p = [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f]; segP(RIB, [p[0], h + 1.6, p[1]], [c[0], T.t, c[1]], 0.07, 3); } }
      avLight(B, c[0], T.t - 0.2, c[1], 0.8);
    }
    B.flush(g); return g; }};

// ---------------------------------------------------------------- Shinjuku Sumitomo Building (210 m, 52 F, 1974) + Triangle Square (2020)
// The triangle with cut corners (OSM footprint) round a full-height triangular atrium (glass roof at the top), a fine aluminium window
// grid; at its foot the Triangle Square under its glass roof (up to about 25 m) on the OSM outline of the plaza.
LANDMARKS.tysumitomo = {zh:'新宿住友大厦', en:'Shinjuku Sumitomo Building', cat:'new', r:62, h:210,
  lt:{m:1, c:'#e6edf8', k:0.6},
  build(){
    const g = new THREE.Group(), B = mkB(), F = FD.tysumitomo, gf = gL('tysumitomo'), H = 210.3;
    const P = F.ring, GLS = {c:'#4d5862', m:1, fh:4.0, cw:2.0}, AL = '#c6c9cb';
    plinthP(B.p('#b8b8b4'), P, gf, 0.2);
    prismP(B.p(GLS), P, 0, H - 4, true, true);
    bandsP(B.p(AL), P, 26, H - 6, 4.0, 2.2, 0.15);
    mullP(B.p(AL), P, 26, H - 6, 1.9, 0.55, 0.16, 0);
    // the cut corners: solid aluminium with a vertical slot
    for (let i = 0; i < P.length; i++){ const a = P[i], b = P[(i+1) % P.length], L = Math.hypot(b[0]-a[0], b[1]-a[1]); if (L > 30) continue;
      const [nx, nz] = outN(P, i); quadP(B.p('#b9bcbe'), [a[0] + nx*0.12, 26, a[1] + nz*0.12], [b[0] + nx*0.12, 26, b[1] + nz*0.12], [b[0] + nx*0.12, H - 6, b[1] + nz*0.12], [a[0] + nx*0.12, H - 6, a[1] + nz*0.12]);
      const m = [(a[0] + b[0])/2, (a[1] + b[1])/2], ux = (b[0]-a[0])/L, uz = (b[1]-a[1])/L;
      quadP(B.p(GLS), [m[0] - ux*1.6 + nx*0.2, 26, m[1] - uz*1.6 + nz*0.2], [m[0] + ux*1.6 + nx*0.2, 26, m[1] + uz*1.6 + nz*0.2], [m[0] + ux*1.6 + nx*0.2, H - 6, m[1] + uz*1.6 + nz*0.2], [m[0] - ux*1.6 + nx*0.2, H - 6, m[1] - uz*1.6 + nz*0.2]); }
    // crown: a solid band and the roof with the triangular atrium skylight
    prismP(B.p('#a9adb0'), offP(P, -0.2), H - 6, H, true, true);
    const IN = (() => { const c = cenP(P); return P.map(p => [c[0] + (p[0]-c[0])*0.4, c[1] + (p[1]-c[1])*0.4]); })();
    { const o = B.p('#9da1a3'); const ring = []; fieldRoof(o, P, [IN.slice().reverse()], () => H, 4); }
    flatP(B.p({c:'#8aa0b0', glow:'#dfe9ff', gk:0.25}), IN, H - 1.2); prismP(B.p('#9da1a3'), IN, H - 1.2, H, true, true);
    edgeP(B.p('#a9adb0'), P, H, 0.4, 1.2, 0);
    { const c = cenP(P); boxP(B.p('#9a9c9e'), 6, 3, 6, P[0][0]*0.3 + c[0]*0.7, H, P[0][1]*0.3 + c[1]*0.7, 0); avLight(B, c[0], H + 0.6, c[1], 0.8); for (const v of [P[0], P[2], P[4]]) avLight(B, v[0]*0.97 + c[0]*0.03, H + 1.3, v[1]*0.97 + c[1]*0.03, 0.6); }
    // Triangle Square: the plaza outline minus the tower, glass walls and a glass roof rising from about 14 m at the edge to 25 m at the tower
    const PZ = F.plaza, dT = (x, z) => inPoly(P, x, z) ? 0 : dPoly(P, x, z), dmax = 30;
    const hf = (x, z) => 14 + 11*(1 - Math.min(1, dT(x, z)/dmax));
    const GLR = B.p({c:'#9fb4c2', glow:'#fff1d6', gk:0.32});
    fieldRoof(GLR, PZ, [P.slice().reverse()], hf, 3);
    for (let i = 0; i < PZ.length; i++){ const a = PZ[i], b = PZ[(i+1) % PZ.length]; quadP(B.p({c:'#7d93a3', glow:'#fff1d6', gk:0.4}), [a[0], gf(a[0], a[1]) - 1, a[1]], [b[0], gf(b[0], b[1]) - 1, b[1]], [b[0], hf(b[0], b[1]), b[1]], [a[0], hf(a[0], a[1]), a[1]]); }
    // roof frame: a grid of white members every 6 m in two directions
    { const FR = B.p('#eef0f0'), bb = bbP(PZ);
      for (let x = Math.ceil(bb[0]/6)*6; x < bb[2]; x += 6){ let pr = null; for (let z = bb[1]; z <= bb[3]; z += 1.5){ const ok = inPoly(PZ, x, z) && !inPoly(P, x, z); const q = ok ? [x, hf(x, z) + 0.15, z] : null; if (q && pr) segP(FR, pr, q, 0.12, 3); pr = q; } }
      for (let z = Math.ceil(bb[1]/6)*6; z < bb[3]; z += 6){ let pr = null; for (let x = bb[0]; x <= bb[2]; x += 1.5){ const ok = inPoly(PZ, x, z) && !inPoly(P, x, z); const q = ok ? [x, hf(x, z) + 0.15, z] : null; if (q && pr) segP(FR, pr, q, 0.12, 3); pr = q; } }
      edgeP(FR, PZ, 13.6, 0.5, 0.6, 0); }
    B.flush(g); return g; }};

place('tytmg1'); place('tytmg2'); place('tycocoon'); place('typarktower'); place('tysumitomo');

